-- Rifts World Book 36: Sovietski - its bestiary and its notable NPCs.
-- 2 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~399-sovietski-dbees-a.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('gridgitz', 'Gridgitz', 'humanoid', 'rifts', 1, 'Any; most are Scrupulous (40%), Unprincipled (25%) or Anarchist (20%).', '{"IQ":"2D6+3","ME":"2D6+9","MA":"1D6+10","PS":"2D6+11","PP":"1D6+10","PE":"2D6+10","PB":"2D6+3","Spd":"2D6+6"}', 'PE+1D6+2', '3D6+30', NULL, '2D6', NULL, 'Hit Points are the P.E. attribute number plus 1D6+2 per level of experience. S.D.C. is 3D6+30 plus any from physical skills. P.P.E. 2D6. I.S.P. only for a psychic: M.E. x3 plus 2D4 per level for a Major psychic, M.E. x2 plus 1D4 per level for a Minor one (the Gridgitz class).', NULL, NULL, '{"disarm":1,"roll":2}', 'Attacks per melee come from the Hand to Hand Combat skill. Racial bonuses, on top of attribute and skill bonuses: +1 disarm, +2 roll with impact, +1 save vs possession, +1 save vs poison, drugs, alcohol and disease, +1 save vs magic.', 'No racial skills; a Gridgitz takes its skills from its O.C.C. (the book points farmers and laborers at the Sovietski Citizen or Russian Villager O.C.C.). The class carries the shared Police Officer, Gridgitz and Infantry Soldier experience table.', 'Nothing beyond its strength, endurance and bonuses. Its body takes cybernetics and Bio-Systems built for humans with no changes at all.', 'None. Gridgitz shun magic as dishonest work and avoid magic items, Techno-Wizard devices included; never a practitioner of magic.', 'Percentile roll, or a pick if the G.M. allows, Healing powers only: 01-25 Major psychic with Deaden Pain and seven more Healing powers; 26-50 Minor psychic with Meditation and three Healing powers; 51-00 none. Never a Psychic O.C.C.', '6 feet to 6 feet 9 inches (1.8 to 2 m)', '200 to 300 lbs (90 to 135 kg)', '2D6+66 years for males, 4D6+70 for females', 'Farmland and the countryside across Russia; every Russian village and city has a few (1D4% of its people). About 4% of the Sovietski''s people are Gridgitz, counted as human.', 'Whatever Russian power rules where they live; they see themselves as wholly Russian. They keep away from woodland spirits but think well of them.', 'Demons, Witches and Necromancers above all, then practitioners of magic, gypsies and non-Russians generally.', 'Any O.C.C. but a magic or Psychic one. Most are farmers and laborers; adventurers lean to Body Fixer, City Rat, Operator, Vagabond, Wilderness Scout, Hunter/Trapper or a Men-at-Arms O.C.C. other than Robot Pilot. Playable as the Gridgitz class.', 'Pronounced GRID-jitz. Big, broad, hairy people who pass for human so well that many only learned they were D-Bees when the Sovietski began genetic screening; they arrived early in the Dark Age and now share Russian speech, faith and habits completely. They are stubborn, honest and proud of hard labor, working and celebrating with equal energy, courteous to strangers yet slow to confide in anyone. About half have some psychic healing gift, which many credit to prayer, and the strongest healers become respected village wise folk or Body Fixers. The state''s propaganda loves them as the model peasant. Most cannot read and know only a language or two besides Russian. As slaves they fetch about a human''s price, double for a trained healer, but they fight captivity and are seldom wanted.', 'Rifts World Book 36: Sovietski p.64-66'),
('shu-shuum', 'Shu-Shuum', 'humanoid', 'rifts', 1, 'Any; most are Principled (33%), Scrupulous (33%), Unprincipled (20%) or Anarchist (10%). Evil ones are very rare and usually Aberrant.', '{"IQ":"2D6+13","ME":"2D6+9","MA":"1D6+6","PS":"1D6+8","PP":"1D6+11","PE":"1D6+10","PB":"1D4+6","Spd":"2D6+2"}', 'PE+2D4', '20', NULL, '2D6', NULL, 'Hit Points are the P.E. attribute number plus 2D4 per level of experience. S.D.C. 20 plus any from physical skills. P.P.E. 2D6. No psionics.', NULL, NULL, '{"perception":2}', 'Fights by the rules for no Hand to Hand Combat skill unless its work demands one, and then usually Basic. Racial bonuses: +2 on Perception Rolls (+4 when hunting for patterns or arithmetic mistakes), +2 save vs disease, +1 save vs possession, +4 save vs insanity.', 'Racial skills, kept with any O.C.C.: Russian and Euro at 99%, four more languages to start, Literacy Russian 90%, Computer Operation +20%, Law (Russian, General) +20%, Mathematics: Advanced +30%, Mathematics: Basic +45%, Research +20%, Sing +15%. These and the Shu-Shuum experience table are on the Shu-Shuum class.', 'Acute Memory: recalls anything it chose to memorize word for word (minus 1D6% when angry, distracted or frightened, 2D6% when lives hang on it); holds 20,000 pages at level one and 1D4x10,000 more per level, and can drop topics to make room. Language: picks up any spoken language at 50% within 2D6 days, +12% per level; literacy starts at +20%. Pattern Recognition: 70% +3% per level to spot an error in figures, a missing item or file, a misplaced object or a telltale detail on a person, and to know its own belongings to the last screw.', 'None, unless the rare Shu-Shuum takes a magic O.C.C.', 'None.', '4 feet to 4 feet 6 inches (1.2 to 1.3 m); stout and nearly as wide as tall', '100 to 150 lbs (45 to 67.5 kg)', '3D6+50 years; mature at 12', 'Russia and Eurasia, about 70% in Sovietski cities; families work for governments and businesses as far as Poland and the NGR, and Warlords, Mindwerks, Triax and the Yama Kings all keep some.', 'The Sovietski, whose Communist Party most of them join, and any large, orderly organization, the European Black Market included. They accept humans and most intelligent races without prejudice.', 'Bullies, loud individualists, jocks and idlers; they fear monsters, demons, evil supernatural beings, human supremacists and slavers.', 'Most need no O.C.C.; their racial skills fit clerical work. A rare adventurer may take Operator, Merchant, Pilot, Rogue Scholar, a Rogue Scientist limited to engineering or chemistry, Smuggler, Vagabond, Wilderness Scout, and very rarely Techno-Wizard or Merc Soldier, with three quarters of the O.C.C. Skills and no O.C.C. Related or Secondary Skills. Playable as the Shu-Shuum class.', 'Pronounced Shoo-SHOOM; nicknamed Grey Dwarves and Cabbage Heads, and by their work Number Crunchers or Money Rollers. Short, squat, grey and deeply wrinkled, with pug noses, small dark eyes, big crumpled ears and a little stringy black hair worn swept back. A Sovietski patrol found their starving tribe in the Ural foothills months after the Rifts brought them, more than 5,000 already dead, and almost all on Earth descend from that group. Ten thousand years as a subject people made them obedient and content with routine, and they are glad of the freedom the Sovietski gives them. They love accounts, logistics, filing and planning, want no power or credit, keep the letter of the law and prefer their own quiet company to loud, towering humans. They save carefully. A trained accountant or manager sells as a slave for 2D4x10,000 credits, half that for a novice.', 'Rifts World Book 36: Sovietski p.66-68');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 creatures are in' AS assertion, count(*) AS got, 2 AS want
  FROM creatures WHERE slug IN ('gridgitz', 'shu-shuum');
SELECT 'and 2 of them are playable' AS assertion, count(*) AS got, 2 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('gridgitz', 'shu-shuum');
SELECT 'the creatures carry 0 attacks' AS assertion, count(*) AS got, 0 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('gridgitz', 'shu-shuum');

